package org.apache.commons.math3.geometry.euclidean.threed;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.geometry.euclidean.oned.Interval;
import org.apache.commons.math3.geometry.euclidean.oned.IntervalsSet;
import org.apache.commons.math3.geometry.euclidean.oned.Vector1D;
import org.apache.commons.math3.geometry.euclidean.threed.IntervalsSet;
import org.apache.commons.math3.geometry.euclidean.threed.Line;
import org.apache.commons.math3.geometry.euclidean.threed.SubLine;
import org.apache.commons.math3.geometry.euclidean.threed.Vector3D;
import org.apache.commons.math3.geometry.partitioning.Region.Location;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for SubLine.getSegments().
 */
public class SubLine_getSegments_TriageGen2Test {

    @Test
    public void testGetSegmentsWithEmptyIntervals() {
        Line line = Line.infiniteLine(Vector3D.PLUS_ONE, Vector3D.PLUS_ONE);
        // IntervalsSet with no intervals
        IntervalsSet emptyIntervals = new IntervalsSet(new double[][]{});
        SubLine subLine = new SubLine(line, emptyIntervals);

        List<Segment> segments = subLine.getSegments();

        assertNotNull(segments);
        assertTrue(segments.isEmpty());
    }

    @Test
    public void testGetSegmentsWithSingleInterval() {
        Line line = Line.infiniteLine(Vector3D.ZERO, Vector3D.PLUS_ONE);
        // One interval from 1.0 to 2.0
        IntervalsSet intervals = new IntervalsSet(new double[][]{{1.0, 2.0}});
        SubLine subLine = new SubLine(line, intervals);

        List<Segment> segments = subLine.getSegments();

        assertNotNull(segments);
        assertEquals(1, segments.size());

        Segment segment = segments.get(0);
        // In the line's space, the start should be 1.0 and end 2.0
        // Since line is (0,0,0) to (1,1,1), toSpace(1.0) is (1,1,1)
        assertEquals(1.0, segment.getStart().getPoint1().getPoint1(), 1e-10); // Simplified check for logic
        // The implementation uses line.toSpace(new Vector1D(inf))
        // We verify the segment properties
        assertEquals(line, segment.getLine());
    }

    @Test
    public void testGetSegmentsWithMultipleIntervals() {
        Line line = Line.infiniteLine(Vector3D.ZERO, Vector3D.PLUS_ONE);
        // Two intervals: [0, 1] and [2, 3]
        IntervalsSet intervals = new IntervalsSet(new double[][]{{0.0, 1.0}, {2.0, 3.0}});
        SubLine subLine = new SubLine(line, intervals);

        List<Segment> segments = subLine.getSegments();

        assertNotNull(segments);
        assertEquals(2, segments.size());

        // Verify first segment
        Segment seg1 = segments.get(0);
        // Check if the start and end points correspond to the interval bounds in line space
        // The toSpace method maps the 1D coordinate to the 3D vector on the line
        // For Line(0, 1), toSpace(0) is (0,0,0) and toSpace(1) is (1,1,1)
        assertEquals(0.0, seg1.getStart().getPoint1().getPoint1(), 1e-10); 
        assertEquals(1.0, seg1.getEnd().getPoint1().getPoint1(), 1e-10);

        // Verify second segment
        Segment seg2 = segments.get(1);
        assertEquals(2.0, seg2.getStart().getPoint1().getPoint1(), 1e-10);
        assertEquals(3.0, seg2.getEnd().getPoint1().getPoint1(), 1e-10);
    }

    @Test
    public void testGetSegmentsWithZeroLengthInterval() {
        Line line = Line.infiniteLine(Vector3D.ZERO, Vector3D.PLUS_ONE);
        // Single point interval [5.0, 5.0]
        IntervalsSet intervals = new IntervalsSet(new double[][]{{5.0, 5.0}});
        SubLine subLine = new SubLine(line, intervals);

        List<Segment> segments = subLine.getSegments();

        assertNotNull(segments);
        assertEquals(1, segments.size());
        Segment segment = segments.get(0);
        assertEquals(segment.getStart(), segment.getEnd());
    }
}
